[B00] {"id":"B00","key":"cache.ttl","value":"030","enabled":true}
[B01] {"id":"B01","key":"auth.mode","value":"legacy","enabled":true}
[B02] {"id":"B02","key":"log.level","value":"info","enabled":false}
